python3 << 'PYEOF'
import pandas as pd
import numpy as np
from datetime import datetime
import os

# Load and clean data
df = pd.read_csv('/app/benchmark/data.csv')
df['recorded_at'] = pd.to_datetime(df['recorded_at'])
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'])
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600

# Filter to reasonable UK fuel prices
df_clean = df[(df['price_pence'] > 50) & (df['price_pence'] < 500)].copy()

# Calculate all statistics
fuel_types_order = ['E10', 'E5', 'B7_STANDARD', 'B7_PREMIUM', 'B10', 'HVO']
fuel_stats_data = {}

for ft in fuel_types_order:
    ft_data = df_clean[df_clean['fuel_type'] == ft]['price_pence']
    fuel_stats_data[ft] = {
        'count': len(ft_data),
        'mean': ft_data.mean(),
        'median': ft_data.median(),
        'min': ft_data.min(),
        'max': ft_data.max(),
        'std': ft_data.std(),
        'Q1': ft_data.quantile(0.25),
        'Q3': ft_data.quantile(0.75),
    }
    fuel_stats_data[ft]['IQR'] = fuel_stats_data[ft]['Q3'] - fuel_stats_data[ft]['Q1']
    fuel_stats_data[ft]['spread'] = fuel_stats_data[ft]['max'] - fuel_stats_data[ft]['min']

# Update lag stats
lag_median = df_clean['update_lag_hours'].median()
lag_mean = df_clean['update_lag_hours'].mean()
lag_max = df_clean['update_lag_hours'].max()
lag_over_24h = (df_clean['update_lag_hours'] > 24).sum()
lag_over_48h = (df_clean['update_lag_hours'] > 48).sum()
lag_over_7d = (df_clean['update_lag_hours'] > 168).sum()

# Station coverage
station_counts = df_clean.groupby('fuel_type')['node_id'].nunique()
total_stations = df_clean['node_id'].nunique()

# Fuels per station
station_fuels = df_clean.groupby('node_id')['fuel_type'].nunique()
fuels_dist = station_fuels.value_counts().sort_index()

# Date range
date_min = df_clean['recorded_at'].min()
date_max = df_clean['recorded_at'].max()

# Load charts
with open('/app/output/chart1.txt', 'r') as f: chart1 = f.read()
with open('/app/output/chart2.txt', 'r') as f: chart2 = f.read()
with open('/app/output/chart3.txt', 'r') as f: chart3 = f.read()
with open('/app/output/chart4.txt', 'r') as f: chart4 = f.read()
with open('/app/output/chart5.txt', 'r') as f: chart5 = f.read()

# Generate HTML report
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
