            box-shadow: 0 10px 40px rgba(0,0,0,0.15);
        }}
        .report-header h1 {{
            font-size: 2.4em;
            margin-bottom: 15px;
            font-weight: 700;
        }}
        .report-header .subtitle {{
            font-size: 1.1em;
