                    <th>Max</th>
                    <th>Std Dev</th>
                </tr>
                <tr><td>E10 (Standard Unleaded)</td><td>{fuel_stats_data['E10']['count']:,}</td><td>{fuel_stats_data['E10']['mean']:.2f}</td><td>{fuel_stats_data['E10']['median']:.2f}</td><td>{fuel_stats_data['E10']['min']:.2f}</td><td>{fuel_stats_data['E10']['max']:.2f}</td><td>{fuel_stats_data['E10']['std']:.2f}</td></tr>
                <tr><td>E5 (Super Unleaded)</td><td>{fuel_stats_data['E5']['count']:,}</td><td>{fuel_stats_data['E5']['mean']:.2f}</td><td>{fuel_stats_data['E5']['median']:.2f}</td><td>{fuel_stats_data['E5']['min']:.2f}</td><td>{fuel_stats_data['E5']['max']:.2f}</td><td>{fuel_stats_data['E5']['std']:.2f}</td></tr>
                <tr><td>B7_STANDARD (Standard Diesel)</td><td>{fuel_stats_data['B7_STANDARD']['count']:,}</td><td>{fuel_stats_data['B7_STANDARD']['mean']:.2f}</td><td>{fuel_stats_data['B7_STANDARD']['median']:.2f}</td><td>{fuel_stats_data['B7_STANDARD']['min']:.2f}</td><td>{fuel_stats_data['B7_STANDARD']['max']:.2f}</td><td>{fuel_stats_data['B7_STANDARD']['std']:.2f}</td></tr>
                <tr><td>B7_PREMIUM (Premium Diesel)</td><td>{fuel_stats_data['B7_PREMIUM']['count']:,}</td><td>{fuel_stats_data['B7_PREMIUM']['mean']:.2f}</td><td>{fuel_stats_data['B7_PREMIUM']['median']:.2f}</td><td>{fuel_stats_data['B7_PREMIUM']['min']:.2f}</td><td>{fuel_stats_data['B7_PREMIUM']['max']:.2f}</td><td>{fuel_stats_data['B7_PREMIUM']['std']:.2f}</td></tr>
                <tr><td>B10</td><td>{fuel_stats_data['B10']['count']:,}</td><td>{fuel_stats_data['B10']['mean']:.2f}</td><td>{fuel_stats_data['B10']['median']:.2f}</td><td>{fuel_stats_data['B10']['min']:.2f}</td><td>{fuel_stats_data['B10']['max']:.2f}</td><td>{fuel_stats_data['B10']['std']:.2f}</td></tr>
                <tr><td>HVO</td><td>{fuel_stats_data['HVO']['count']:,}</td><td>{fuel_stats_data['HVO']['mean']:.2f}</td><td>{fuel_stats_data['HVO']['median']:.2f}</td><td>{fuel_stats_data['HVO']['min']:.2f}</td><td>{fuel_stats_data['HVO']['max']:.2f}</td><td>{fuel_stats_data['HVO']['std']:.2f}</td></tr>
