                <tr><td>B7_PREMIUM</td><td>{fuel_stats_data['B7_PREMIUM']['mean']:.2f}p</td><td>{fuel_stats_data['B7_PREMIUM']['median']:.2f}p</td><td>{fuel_stats_data['B7_PREMIUM']['IQR']:.2f}p</td><td>{fuel_stats_data['B7_PREMIUM']['spread']:.2f}p</td><td><span class="badge badge-success">Moderate spread</span></td></tr>
                <tr><td>B10</td><td>{fuel_stats_data['B10']['mean']:.2f}p</td><td>{fuel_stats_data['B10']['median']:.2f}p</td><td>{fuel_stats_data['B10']['IQR']:.2f}p</td><td>{fuel_stats_data['B10']['spread']:.2f}p</td><td><span class="badge badge-warning">Limited data</span></td></tr>
                <tr><td>HVO</td><td>{fuel_stats_data['HVO']['mean']:.2f}p</td><td>{fuel_stats_data['HVO']['median']:.2f}p</td><td>{fuel_stats_data['HVO']['IQR']:.2f}p</td><td>{fuel_stats_data['HVO']['spread']:.2f}p</td><td><span class="badge badge-warning">Limited data</span></td></tr>
            </table>

